// Generated by Viscosity: "bodies" stored as a struct of arrays (fields x, y, m).
class __Vsc_bodies {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.x = new Float64Array(cap); this.y = new Float64Array(cap); this.m = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_bodies(Math.max(16, v.length / 3)); for (let i = 0; i < v.length; i += 3) c.push(v[i + 0], v[i + 1], v[i + 2]); return c; }
  push(v0, v1, v2) { const n = this.length; if (n === this.cap) this.grow(); this.x[n] = v0; this.y[n] = v1; this.m[n] = v2; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.x); this.x = t; t = new Float64Array(cap); t.set(this.y); this.y = t; t = new Float64Array(cap); t.set(this.m); this.m = t; }
}
// viscosity: bodies=soa
const bodies = new __Vsc_bodies();
for (let i = 0; i < 200; i++) bodies.push(i, i * 2, 1 + (i % 3));
function centerOfMass(bs) {
  let mx = 0;
  let m = 0;
  for (let b = 0; b < bs.length; b++) { mx += bs.x[b] * bs.m[b]; m += bs.m[b]; }
  return mx / m;
}
function drift(bs, dx) {
  for (let i = 0; i < bs.length; i++) bs.x[i] += dx;
}
drift(bodies, 0.5);
drift(bodies, -0.25);
console.log(centerOfMass(bodies));
